def page_count(total_items, per_page):
    """Number of pages needed to show all items, with a partial final page counted.
    Zero items means zero pages."""
    if total_items == 0:
        return 0
    return (total_items + per_page - 1) // per_page

def windows(items, size):
    """Every consecutive run of exactly `size` elements, in order.
    Fewer items than `size` gives an empty list."""
    if len(items) < size:
        return []
    return [items[i:i+size] for i in range(len(items) - size + 1)]

def between(value, low, high):
    """True when value lies strictly between low and high, touching neither end."""
    return low < value < high

def nth_from_end(items, n):
    """The nth element counting back from the end, where n=1 is the last element."""
    return items[-n]

def split_at(items, index):
    """Split into (before, after) where `before` holds the first `index` elements."""
    return (items[:index], items[index:])

def overlap(a_start, a_end, b_start, b_end):
    """True when two half-open intervals [start, end) share at least one point."""
    return a_start < b_end and b_start < a_end

def insert_sorted(items, value):
    """Insert into a sorted list, placing the value AFTER any equal values."""
    i = 0
    while i < len(items) and items[i] <= value:
        i += 1
    return items[:i] + [value] + items[i:]

def clip_exclusive(index, length):
    """Clip an index into the valid positions of a sequence of `length` items."""
    return max(0, min(index, length - 1))

def countdown(start):
    """Every whole number from `start` down to 1, in order. Zero or less gives nothing."""
    if start <= 0:
        return []
    return list(range(start, 0, -1))

def trim_to_fit(words, width):
    """Take words from the front while the joined line stays within `width` characters,
    counting the single spaces between them."""
    result = []
    for word in words:
        if result:
            new_length = len(' '.join(result)) + 1 + len(word)
        else:
            new_length = len(word)
        if new_length <= width:
            result.append(word)
        else:
            break
    return result

def progress(done, total, width):
    """How many cells of a bar `width` wide should be filled, rounded down.
    A finished job fills every cell; zero total fills none."""
    if total == 0:
        return 0
    return int((done / total) * width)
